-- ── 보조 함수 — 이 파일 안에서만 쓰고 끝에서 지운다(pg_temp) ─────────────────────────────────────────────

-- 운행일의 요일 문자열(route · schedule · weekly_address 의 weekday 값)
CREATE OR REPLACE FUNCTION pg_temp.qa_wd(d date) RETURNS text LANGUAGE sql IMMUTABLE AS $f$
    SELECT (ARRAY['sun','mon','tue','wed','thu','fri','sat'])[extract(dow FROM d)::int + 1]
$f$;

-- 결정적 0~99 — 같은 시드는 같은 학생이 결석·미승차가 된다(적용할 때마다 바뀌지 않게)
CREATE OR REPLACE FUNCTION pg_temp.qa_h(t text) RETURNS int LANGUAGE sql IMMUTABLE AS $f$
    SELECT abs(hashtext(t)) % 100
$f$;

-- 알림 1건 — 단말 토큰이 있으면 sent, 없으면 skipped. 6시간 넘은 알림은 대부분 읽음, 최근 것은 일부만 읽음.
CREATE OR REPLACE FUNCTION pg_temp.qa_notify(p_account bigint, p_role text, p_student bigint, p_run bigint, p_type text,
        p_title text, p_body text, p_at timestamptz, p_key text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
    v_has_token boolean := EXISTS (SELECT 1 FROM device_token t WHERE t.account_id = p_account AND t.revoked_at IS NULL);
    v_h int := pg_temp.qa_h(p_key);
BEGIN
    IF p_at > now() THEN
        RETURN;
    END IF;
    INSERT INTO notification_log (academy_id, recipient_account_id, recipient_name, recipient_role, student_id, student_name,
                                  bus_no, run_id, type, title, body, popup, push_state, push_attempts, last_attempt_at,
                                  dedup_key, created_at, sent_at, read_at)
    SELECT COALESCE(r.academy_id, a.academy_id), a.id, a.name, p_role, s.id, s.name, b.bus_no, p_run, p_type, p_title, p_body,
           p_type IN ('emergency', 'no_show_escalated'),
           CASE WHEN v_has_token THEN 'sent' ELSE 'skipped' END,
           CASE WHEN v_has_token THEN 1 ELSE 0 END,
           CASE WHEN v_has_token THEN p_at + interval '1 second' END,
           p_key, p_at,
           CASE WHEN v_has_token THEN p_at + interval '2 seconds' END,
           CASE WHEN p_at < now() - interval '6 hours' AND v_h < 85 THEN p_at + make_interval(mins => 1 + v_h)
                WHEN v_h < 25 THEN LEAST(now(), p_at + interval '3 minutes') END
    FROM account a
    LEFT JOIN run r ON r.id = p_run
    LEFT JOIN bus b ON b.id = r.bus_id
    LEFT JOIN student s ON s.id = p_student
    WHERE a.id = p_account
    ON CONFLICT (dedup_key) DO NOTHING;
END
$f$;

-- 학생의 보호자 계정들
CREATE OR REPLACE FUNCTION pg_temp.qa_guardians(p_student bigint) RETURNS SETOF bigint LANGUAGE sql STABLE AS $f$
    SELECT g.account_id FROM guardian_student gs JOIN guardian g ON g.id = gs.guardian_id
    WHERE gs.student_id = p_student AND gs.unlinked_at IS NULL
$f$;

-- 변경 요청 1건(+ 결정 알림). 반환 = change_request id
CREATE OR REPLACE FUNCTION pg_temp.qa_request(p_run bigint, p_student bigint, p_source text, p_type text, p_status text,
        p_segment int, p_requested_at timestamptz, p_new_stop bigint, p_reason text, p_decided_at timestamptz,
        p_reject_reason text) RETURNS bigint LANGUAGE plpgsql AS $f$
DECLARE
    v_run run%ROWTYPE;
    v_requester bigint := (SELECT g FROM pg_temp.qa_guardians(p_student) g LIMIT 1);
    v_staff bigint;
    v_addr text; v_lat numeric; v_lng numeric;
    v_id bigint;
    v_name text := (SELECT name FROM student WHERE id = p_student);
BEGIN
    SELECT * INTO v_run FROM run WHERE id = p_run;
    v_staff := (SELECT account_id FROM academy_staff WHERE academy_id = v_run.academy_id AND status = 'active');
    IF v_requester IS NULL THEN
        v_requester := v_staff;
    END IF;
    IF p_new_stop IS NOT NULL THEN
        SELECT address, lat, lng INTO v_addr, v_lat, v_lng FROM stop WHERE id = p_new_stop;
    ELSIF p_type = 'relocate' THEN
        -- 승하차지가 아닌 위치로의 변경 요청(예: 학원 앞) — 주소는 그 위치, 승하차지는 비운다
        SELECT address, lat, lng INTO v_addr, v_lat, v_lng FROM academy WHERE id = v_run.academy_id;
    END IF;
    INSERT INTO change_request (academy_id, run_id, student_id, source, type, status, window_segment, new_address, new_lat,
                                new_lng, new_stop_id, reason, requested_by, requested_at, deadline_at, decided_by, decided_at,
                                reject_reason)
    VALUES (v_run.academy_id, p_run, p_student, p_source, p_type, p_status, p_segment, v_addr, v_lat, v_lng,
            p_new_stop, p_reason, v_requester, p_requested_at,
            CASE WHEN p_segment = 2 THEN v_run.depart_time END,
            CASE WHEN p_status IN ('approved', 'rejected') AND p_segment = 2 THEN v_staff END,
            CASE WHEN p_status <> 'pending' THEN COALESCE(p_decided_at, p_requested_at) END,
            p_reject_reason)
    RETURNING id INTO v_id;
    IF p_segment = 2 THEN
        INSERT INTO boarding_intent (run_id, student_id, riding, change_used_count, applied_segment, changed_at, changed_by, created_at)
        VALUES (p_run, p_student, NOT (p_type = 'cancel' AND p_status = 'approved'), 1, 2, p_requested_at, v_requester, p_requested_at)
        ON CONFLICT (run_id, student_id) DO UPDATE SET change_used_count = 1, changed_at = EXCLUDED.changed_at;
        PERFORM pg_temp.qa_notify(v_staff, 'staff', p_student, p_run, 'approval_requested', '변경 승인 요청',
                '학부모의 일일 변경 요청이 접수되어 승인이 필요합니다. 앱에서 확인해 주세요.', p_requested_at,
                format('approval_requested:%s:%s:%s', p_run, v_staff, v_id));
        IF p_status = 'approved' THEN
            PERFORM pg_temp.qa_notify(v_requester, 'parent', p_student, p_run, 'change_decided', '변경 요청 승인 안내',
                    format('%s 학생의 승하차 변경 요청이 승인되어 반영되었습니다.', v_name), p_decided_at,
                    format('change_decided:%s:%s:%s', p_run, v_id, p_decided_at));
        ELSIF p_status = 'rejected' THEN
            PERFORM pg_temp.qa_notify(v_requester, 'parent', p_student, p_run, 'change_decided', '변경 요청 거절 안내',
                    format('%s 학생의 승하차 변경 요청이 거절되었습니다. 사유: %s', v_name, p_reject_reason), p_decided_at,
                    format('change_decided:%s:%s:%s', p_run, v_id, p_decided_at));
        ELSIF p_status = 'auto_rejected' THEN
            PERFORM pg_temp.qa_notify(v_requester, 'parent', p_student, p_run, 'change_decided', '변경 요청 처리 안내',
                    format('%s 학생의 요청하신 변경이 처리 기한 안에 확인되지 않아 반영되지 않았습니다. 기존 승하차 정보가 그대로 유지됩니다.', v_name),
                    p_decided_at, format('change_decided:%s:%s:%s', p_run, v_id, p_decided_at));
        END IF;
    ELSIF p_type = 'cancel' AND p_status = 'approved' THEN
        -- ①구간 취소는 즉시 반영 — 탑승 의사 OFF + 관계자 미탑승 통지
        INSERT INTO boarding_intent (run_id, student_id, riding, change_used_count, applied_segment, changed_at, changed_by, created_at)
        VALUES (p_run, p_student, false, 0, 1, p_requested_at, v_requester, p_requested_at)
        ON CONFLICT (run_id, student_id) DO UPDATE SET riding = false, applied_segment = 1, changed_at = EXCLUDED.changed_at;
        PERFORM pg_temp.qa_notify(v_staff, 'staff', p_student, p_run, 'absent', '미탑승 안내',
                '학생 한 명이 이 회차에 타지 않습니다. 명단에서 확인해 주세요.', p_requested_at,
                format('absent:%s:staff:%s:student:%s:%s', p_run, v_staff, p_student, p_requested_at));
    END IF;
    RETURN v_id;
END
$f$;

-- 회차 1개 — 상태에 맞춰 확정 노선 · 정차 · 탑승자 · 승하차 이력 · 알림까지 앱이 만드는 모양 그대로 쌓는다.
--   p_state     idle · confirmed · moving · finished
--   p_progress  moving 일 때 지나간 승하차지 수(등원: 태운 곳 · 하원: 내린 곳)
--   p_assign    정규 기사·동승자 배치 여부(false 면 관계자가 배치할 회차)
CREATE OR REPLACE FUNCTION pg_temp.qa_run(p_bus bigint, p_dir text, p_depart timestamptz, p_state text, p_progress int,
        p_assign boolean) RETURNS bigint LANGUAGE plpgsql AS $f$
DECLARE
    v_academy bigint; v_bus_no text; v_rk text; v_driver bigint; v_escort bigint;
    v_driver_acc bigint; v_escort_acc bigint; v_staff bigint;
    v_date date := (p_depart AT TIME ZONE 'Asia/Seoul')::date;
    v_wd text := pg_temp.qa_wd((p_depart AT TIME ZONE 'Asia/Seoul')::date);
    v_route bigint; v_sched bigint; v_origin text; v_dest text;
    v_est int; v_dist numeric; v_path jsonb;
    v_run bigint; v_ver bigint;
    v_confirm timestamptz := p_depart - interval '30 minutes';
    v_confirmed timestamptz := p_depart - interval '30 minutes' + interval '6 seconds';
    v_started timestamptz; v_finished timestamptz; v_step interval;
    r record; g bigint; v_rider bigint; v_status text; v_eta timestamptz; v_h int; v_passed boolean;
    v_board_at timestamptz; v_alight_at timestamptz; v_case bigint; v_student_acc bigint;
    v_reasons text[] := ARRAY['병원 진료 예약이 있어요', '가족 행사로 결석합니다', '감기로 학교도 결석했어요',
                              '학교 현장체험학습 일정', '오늘은 보호자가 직접 데려다줄게요'];
BEGIN
    SELECT b.academy_id, b.bus_no, q.route_key, q.driver_mgr, q.escort_mgr
      INTO v_academy, v_bus_no, v_rk, v_driver, v_escort
      FROM bus b JOIN qa_bus q ON q.bus_id = b.id WHERE b.id = p_bus;
    v_driver_acc := (SELECT account_id FROM manager WHERE id = v_driver);
    v_escort_acc := (SELECT account_id FROM manager WHERE id = v_escort);
    v_staff := (SELECT account_id FROM academy_staff WHERE academy_id = v_academy AND status = 'active');
    SELECT id INTO v_route FROM route WHERE bus_id = p_bus AND weekday = v_wd AND direction = p_dir;
    SELECT id, origin_name, destination_name INTO v_sched, v_origin, v_dest
      FROM schedule WHERE bus_id = p_bus AND weekday = v_wd AND direction = p_dir;
    SELECT est_min, dist_km, CASE WHEN p_dir = 'to_academy' THEN path ELSE rev_path END
      INTO v_est, v_dist, v_path FROM qa_road WHERE route_key = v_rk;
    v_step := make_interval(secs => v_est * 60 / 10.0);
    v_started := p_depart + make_interval(secs => pg_temp.qa_h(p_bus || p_dir || v_date) % 120);
    v_finished := v_started + make_interval(mins => v_est + 2);

    INSERT INTO run (academy_id, bus_id, schedule_id, service_date, direction, depart_time, confirm_at, status, origin_name,
                     destination_name, est_duration_min, confirmed_at, started_at, finished_at, created_at, updated_at)
    VALUES (v_academy, p_bus, v_sched, v_date, p_dir, p_depart, v_confirm, p_state, v_origin, v_dest, v_est,
            CASE WHEN p_state <> 'idle' THEN v_confirmed END,
            CASE WHEN p_state IN ('moving', 'finished') THEN v_started END,
            CASE WHEN p_state = 'finished' THEN v_finished END,
            LEAST(now(), p_depart - interval '1 day'), now())
    ON CONFLICT ON CONSTRAINT uk_run_bus_date_direction_depart DO NOTHING
    RETURNING id INTO v_run;
    IF v_run IS NULL THEN
        RETURN NULL;
    END IF;
    IF p_assign THEN
        INSERT INTO assignment (run_id, manager_id, role, assigned_at, assigned_by)
        VALUES (v_run, v_driver, 'driver', LEAST(now(), v_confirm - interval '3 hours'), v_staff),
               (v_run, v_escort, 'escort', LEAST(now(), v_confirm - interval '3 hours'), v_staff);
    END IF;
    IF p_state = 'idle' THEN
        RETURN v_run;
    END IF;

    -- 확정 전에 접수된 결석(①구간 취소 · 즉시 반영) — 학생마다 결정적으로 약 4%
    FOR r IN
        SELECT DISTINCT s.id AS sid
        FROM weekly_address wa
        JOIN student s ON s.id = wa.student_id AND s.deleted_at IS NULL AND s.academy_id = v_academy
        JOIN route_stop rs ON rs.route_id = v_route AND rs.stop_id = wa.stop_id
        WHERE wa.weekday = v_wd AND wa.direction = p_dir AND pg_temp.qa_h(v_run || '-' || s.id) < 4
    LOOP
        PERFORM pg_temp.qa_request(v_run, r.sid, 'change_request', 'cancel', 'approved', 1,
                v_confirm - make_interval(hours => 2 + pg_temp.qa_h(r.sid::text) % 20), NULL,
                v_reasons[1 + pg_temp.qa_h('reason' || v_run || r.sid) % 5], NULL, NULL);
    END LOOP;

    INSERT INTO confirmed_route (run_id, confirmed_at) VALUES (v_run, v_confirmed);
    INSERT INTO route_version (confirmed_route_id, version_no, source, est_duration_min, est_distance_km, published_at,
                               input_fingerprint, engine_name, policy_snapshot, fallback_used, road_path, created_at)
    VALUES (v_run, 1, 'confirm_batch', v_est, v_dist, v_confirmed, md5('qa-seed-' || v_run), 'nearest-neighbor', '{}'::jsonb,
            false, v_path, v_confirmed)
    RETURNING id INTO v_ver;
    UPDATE confirmed_route SET current_version_id = v_ver WHERE run_id = v_run;

    FOR r IN SELECT rs.seq, rs.stop_id FROM route_stop rs WHERE rs.route_id = v_route ORDER BY rs.seq LOOP
        v_eta := CASE WHEN p_dir = 'to_academy' THEN p_depart + v_step * (r.seq - 1) ELSE p_depart + v_step * r.seq END;
        v_passed := p_state = 'finished' OR (p_state = 'moving' AND r.seq <= p_progress);
        INSERT INTO run_stop (route_version_id, stop_id, seq, eta, arrived_at, departed_at, proximity_notified_at)
        VALUES (v_ver, r.stop_id, r.seq, v_eta,
                CASE WHEN v_passed THEN v_eta + make_interval(secs => pg_temp.qa_h(v_run || 's' || r.seq) % 50) END,
                CASE WHEN v_passed THEN v_eta + make_interval(secs => 60 + pg_temp.qa_h(v_run || 's' || r.seq) % 50) END,
                CASE WHEN v_passed THEN v_eta - interval '2 minutes' END);
    END LOOP;
    IF p_dir = 'to_academy' THEN
        INSERT INTO run_stop (route_version_id, seq, eta, arrived_at, departed_at, destination)
        VALUES (v_ver, 11, p_depart + make_interval(mins => v_est),
                CASE WHEN p_state = 'finished' THEN v_finished - interval '1 minute' END,
                CASE WHEN p_state = 'finished' THEN v_finished END, true);
    END IF;

    -- 노선 확정 알림(기사 · 동승자)
    IF p_assign THEN
        PERFORM pg_temp.qa_notify(v_driver_acc, 'driver', NULL, v_run, 'route_changed', '노선 변경 안내',
                '배정된 회차의 노선이 확정·변경되었습니다. 앱에서 새 노선을 확인해 주세요.', v_confirmed,
                format('route_changed:%s:%s:%s', v_run, v_driver, v_confirmed));
        PERFORM pg_temp.qa_notify(v_escort_acc, 'escort', NULL, v_run, 'route_changed', '노선 변경 안내',
                '배정된 회차의 노선이 확정·변경되었습니다. 앱에서 새 노선을 확인해 주세요.', v_confirmed,
                format('route_changed:%s:%s:%s', v_run, v_escort, v_confirmed));
        UPDATE assignment SET acked_route_version_id = v_ver, acked_at = v_confirmed + interval '4 minutes'
        WHERE run_id = v_run AND v_confirmed + interval '4 minutes' < now();
    END IF;
    IF p_state IN ('moving', 'finished') THEN
        PERFORM pg_temp.qa_notify(v_staff, 'staff', NULL, v_run, 'run_started', '운행 시작 안내', '배정된 회차의 운행이 시작되었습니다.',
                v_started, format('run_started:%s:staff:%s:%s', v_run, v_staff, v_started));
    END IF;
    IF p_state = 'finished' THEN
        PERFORM pg_temp.qa_notify(v_staff, 'staff', NULL, v_run, 'run_ended', '운행 종료 안내', '회차 운행이 종료되었습니다.',
                v_finished, format('run_ended:%s:staff:%s:%s', v_run, v_staff, v_finished));
    END IF;

    -- 탑승자 — 고정 노선 승하차지에 그 요일·방향 주소가 걸린 학생(확정 배치의 명단 규칙)
    FOR r IN
        SELECT DISTINCT ON (s.id) s.id AS sid, s.name AS sname, s.account_id AS sacc, wa.stop_id, rs.seq
        FROM weekly_address wa
        JOIN student s ON s.id = wa.student_id AND s.deleted_at IS NULL AND s.academy_id = v_academy
        JOIN route_stop rs ON rs.route_id = v_route AND rs.stop_id = wa.stop_id
        WHERE wa.weekday = v_wd AND wa.direction = p_dir
        ORDER BY s.id
    LOOP
        v_h := pg_temp.qa_h(v_run || '-' || r.sid);
        v_eta := CASE WHEN p_dir = 'to_academy' THEN p_depart + v_step * (r.seq - 1) ELSE p_depart + v_step * r.seq END;
        v_passed := p_state = 'finished' OR (p_state = 'moving' AND r.seq <= p_progress);
        v_board_at := CASE WHEN p_dir = 'to_academy' THEN v_eta + interval '20 seconds' ELSE v_started - interval '1 minute' END;
        v_alight_at := CASE WHEN p_dir = 'to_academy' THEN v_finished - interval '50 seconds' ELSE v_eta + interval '30 seconds' END;
        v_status := CASE
            WHEN v_h < 4 THEN 'absent'
            WHEN p_dir = 'to_academy' AND v_h < 6 AND v_passed THEN 'no_show'
            WHEN p_state = 'finished' THEN 'alighted'
            WHEN p_state = 'moving' AND p_dir = 'to_academy' THEN CASE WHEN v_passed THEN 'boarded' ELSE 'waiting' END
            WHEN p_state = 'moving' THEN CASE WHEN v_passed THEN 'alighted' ELSE 'boarded' END
            ELSE 'waiting' END;
        INSERT INTO run_rider (run_id, student_id, stop_id, status, changed_at, created_at, updated_at)
        VALUES (v_run, r.sid, r.stop_id, v_status,
                CASE v_status WHEN 'absent' THEN v_confirmed WHEN 'boarded' THEN v_board_at WHEN 'alighted' THEN v_alight_at
                              WHEN 'no_show' THEN v_eta + interval '3 minutes' END,
                v_confirmed, now())
        RETURNING id INTO v_rider;

        IF v_status = 'absent' THEN
            INSERT INTO rider_status_history (run_rider_id, from_status, to_status, reason, changed_at, actor_type)
            VALUES (v_rider, NULL, 'absent', '확정 전 미탑승 신청', v_confirmed, 'system');
            CONTINUE;
        END IF;
        -- 출발 알림(보호자 · 학생 계정)
        IF p_state IN ('moving', 'finished') THEN
            FOR g IN SELECT * FROM pg_temp.qa_guardians(r.sid) LOOP
                PERFORM pg_temp.qa_notify(g, 'parent', r.sid, v_run, 'run_started', '운행 시작 안내', '배정된 회차의 운행이 시작되었습니다.',
                        v_started, format('run_started:%s:guardian:%s:%s:%s', v_run, g, r.sid, v_started));
            END LOOP;
            IF r.sacc IS NOT NULL THEN
                PERFORM pg_temp.qa_notify(r.sacc, 'student', r.sid, v_run, 'run_started', '운행 시작 안내', '배정된 회차의 운행이 시작되었습니다.',
                        v_started, format('run_started:%s:student:%s:%s', v_run, r.sacc, v_started));
            END IF;
        END IF;
        IF NOT v_passed AND NOT (p_dir = 'from_academy' AND p_state = 'moving') THEN
            CONTINUE;
        END IF;
        -- 도착 임박 알림(지나간 승하차지만)
        IF v_passed THEN
            FOR g IN SELECT * FROM pg_temp.qa_guardians(r.sid) LOOP
                PERFORM pg_temp.qa_notify(g, 'parent', r.sid, v_run, 'arrive', '곧 도착합니다',
                        format('%s 학생이 탄 버스가 승하차지 근처에 도착했습니다.', r.sname), v_eta - interval '2 minutes',
                        format('approaching:%s:%s:%s:guardian:%s', v_run, r.stop_id, r.sid, g));
            END LOOP;
        END IF;
        IF v_status = 'no_show' THEN
            INSERT INTO rider_status_history (run_rider_id, from_status, to_status, reason, verify_method, client_key, occurred_at,
                                              changed_at, actor_type, changed_by)
            VALUES (v_rider, 'waiting', 'no_show', '승하차지에 나오지 않음', 'manual', gen_random_uuid(), v_eta + interval '3 minutes',
                    v_eta + interval '3 minutes', 'escort', v_escort_acc);
            INSERT INTO no_show_case (run_rider_id, started_at, expires_at, resolved_at, decision)
            VALUES (v_rider, v_eta, v_eta + interval '3 minutes', v_eta + interval '4 minutes', 'depart')
            RETURNING id INTO v_case;
            INSERT INTO no_show_contact (no_show_case_id, attempt_type, result, decision, attempted_at, attempted_by)
            VALUES (v_case, 'call', 'no_answer', NULL, v_eta + interval '1 minute', v_escort_acc),
                   (v_case, 'message', 'no_answer', 'depart', v_eta + interval '3 minutes', v_escort_acc);
            FOR g IN SELECT * FROM pg_temp.qa_guardians(r.sid) LOOP
                PERFORM pg_temp.qa_notify(g, 'parent', r.sid, v_run, 'no_show', '미승차 안내',
                        format('%s 학생이 아직 버스에 탑승하지 않았습니다. 확인해 주세요.', r.sname), v_eta + interval '3 minutes',
                        format('stop_departed:%s:%s:no_show', v_rider, g));
            END LOOP;
            PERFORM pg_temp.qa_notify(v_staff, 'staff', r.sid, v_run, 'no_show', '미승차 발생',
                    '학생 한 명이 미승차로 확인됐습니다. 명단에서 확인해 주세요.', v_eta + interval '3 minutes',
                    format('no_show_staff:%s:%s:%s', v_rider, v_staff, v_eta));
            CONTINUE;
        END IF;
        -- 승차
        INSERT INTO rider_status_history (run_rider_id, from_status, to_status, verify_method, client_key, occurred_at, changed_at,
                                          actor_type, changed_by)
        VALUES (v_rider, 'waiting', 'boarded', CASE WHEN v_h % 3 = 0 THEN 'photo' ELSE 'manual' END, gen_random_uuid(),
                v_board_at, v_board_at, 'escort', v_escort_acc);
        FOR g IN SELECT * FROM pg_temp.qa_guardians(r.sid) LOOP
            PERFORM pg_temp.qa_notify(g, 'parent', r.sid, v_run, 'boarding', '승하차 안내',
                    format('%s 학생이 버스에 탑승했습니다.', r.sname), v_board_at, format('stop_departed:%s:%s:boarded', v_rider, g));
        END LOOP;
        IF v_status <> 'alighted' THEN
            CONTINUE;
        END IF;
        -- 하차
        INSERT INTO rider_status_history (run_rider_id, from_status, to_status, verify_method, client_key, occurred_at, changed_at,
                                          actor_type, changed_by)
        VALUES (v_rider, 'boarded', 'alighted', 'manual', gen_random_uuid(), v_alight_at, v_alight_at, 'escort', v_escort_acc);
        FOR g IN SELECT * FROM pg_temp.qa_guardians(r.sid) LOOP
            PERFORM pg_temp.qa_notify(g, 'parent', r.sid, v_run, 'alighting', '승하차 안내',
                    format('%s 학생이 버스에서 하차했습니다.', r.sname), v_alight_at, format('stop_departed:%s:%s:alighted', v_rider, g));
        END LOOP;
    END LOOP;
    RETURN v_run;
END
$f$;

-- ── 생성 ────────────────────────────────────────────────────────────────────────────────────────────
DO $main$
DECLARE
    T timestamptz := date_trunc('minute', now());
    v_today date := (now() AT TIME ZONE 'Asia/Seoul')::date;
    d date;
    s record;
    v_run bigint;
    v_runs bigint[];
    v_a3_to bigint; v_a1_from bigint; v_a2_to bigint;
    v_ids bigint[];
    v_cr bigint;
    v_staff_a bigint := (SELECT account_id FROM academy_staff WHERE academy_id = 1 AND status = 'active');
    v_sys bigint := (SELECT account_id FROM system_admin LIMIT 1);
    v_rider bigint;
    v_alert bigint;
    a record;
BEGIN
    -- ① 지난 7일 — 정기 스케줄 시각의 끝난 운행. 사흘 전 3호차 하원은 기상 악화로 관계자가 임시 취소,
    --    이틀 전 3호차 하원은 종료되지 않은 채 남은 회차
    FOR d IN SELECT generate_series(v_today - 7, v_today - 1, interval '1 day')::date LOOP
        FOR s IN SELECT * FROM schedule WHERE weekday = pg_temp.qa_wd(d) AND active ORDER BY bus_id, direction DESC LOOP
            IF d = v_today - 3 AND s.bus_id = 3 AND s.direction = 'from_academy' THEN
                INSERT INTO run (academy_id, bus_id, schedule_id, service_date, direction, depart_time, confirm_at, status,
                                 origin_name, destination_name, est_duration_min, canceled_at, cancel_source, created_at)
                VALUES (s.academy_id, s.bus_id, s.id, d, s.direction, (d + s.depart_time) AT TIME ZONE 'Asia/Seoul',
                        ((d + s.depart_time) AT TIME ZONE 'Asia/Seoul') - interval '30 minutes', 'idle', s.origin_name,
                        s.destination_name, s.est_duration_min, ((d + s.depart_time) AT TIME ZONE 'Asia/Seoul') - interval '3 hours',
                        'staff', ((d + s.depart_time) AT TIME ZONE 'Asia/Seoul') - interval '1 day');
            ELSIF d = v_today - 2 AND s.bus_id = 3 AND s.direction = 'from_academy' THEN
                -- 기사가 종료를 누르지 않고 남은 회차 — 메인 관리자 '끝나지 않은 회차' 강제 종료 대상(Ruling 724)
                PERFORM pg_temp.qa_run(s.bus_id, s.direction, (d + s.depart_time) AT TIME ZONE 'Asia/Seoul', 'moving', 6, true);
            ELSE
                PERFORM pg_temp.qa_run(s.bus_id, s.direction, (d + s.depart_time) AT TIME ZONE 'Asia/Seoul', 'finished', 10, true);
            END IF;
        END LOOP;
    END LOOP;

    -- ② 오늘 — 초기화 시각 T 기준. 상태가 고르게 섞이도록(끝남 · 운행 중 · 확정 · 확정 전)
    PERFORM pg_temp.qa_run(1, 'to_academy',   T - interval '75 minutes', 'finished', 10, true);
    v_a2_to   := pg_temp.qa_run(2, 'to_academy',   T - interval '3 minutes',  'moving',    0, true);
    v_a3_to   := pg_temp.qa_run(3, 'to_academy',   T + interval '18 minutes', 'confirmed', 0, true);
    v_a1_from := pg_temp.qa_run(1, 'from_academy', T + interval '50 minutes', 'idle',      0, true);
    PERFORM pg_temp.qa_run(2, 'from_academy', T + interval '80 minutes',  'idle', 0, true);
    PERFORM pg_temp.qa_run(3, 'from_academy', T + interval '150 minutes', 'idle', 0, false);
    PERFORM pg_temp.qa_run(5, 'to_academy',   T - interval '8 minutes',   'moving', 3, true);
    PERFORM pg_temp.qa_run(5, 'from_academy', T + interval '35 minutes',  'idle', 0, true);

    -- ③ 내일 — 정기 스케줄 시각, 확정 전. 3호차는 관계자가 기사를 배치해야 하는 상태로 둔다
    FOR s IN SELECT * FROM schedule WHERE weekday = pg_temp.qa_wd(v_today + 1) AND active ORDER BY bus_id, direction DESC LOOP
        PERFORM pg_temp.qa_run(s.bus_id, s.direction, ((v_today + 1) + s.depart_time) AT TIME ZONE 'Asia/Seoul', 'idle', 0,
                               s.bus_id <> 3);
    END LOOP;

    -- ④ 변경 요청 — 오늘 3호차 등원(②구간: 승인 대기 3 · 거절 1)
    SELECT array_agg(student_id ORDER BY stop_id, student_id) INTO v_ids FROM run_rider WHERE run_id = v_a3_to AND status = 'waiting';
    IF array_length(v_ids, 1) >= 4 THEN
        PERFORM pg_temp.qa_request(v_a3_to, v_ids[1], 'intent', 'cancel', 'pending', 2, T - interval '9 minutes', NULL, NULL, NULL, NULL);
        PERFORM pg_temp.qa_request(v_a3_to, v_ids[4], 'intent', 'cancel', 'pending', 2, T - interval '6 minutes', NULL, NULL, NULL, NULL);
        PERFORM pg_temp.qa_request(v_a3_to, v_ids[7], 'change_request', 'relocate', 'pending', 2, T - interval '4 minutes',
                (SELECT stop_id FROM run_rider WHERE run_id = v_a3_to AND student_id = v_ids[1]),
                '오늘은 친구 집에서 숙제하고 그 단지 앞에서 탈게요', NULL, NULL);
        PERFORM pg_temp.qa_request(v_a3_to, v_ids[10], 'intent', 'cancel', 'rejected', 2, T - interval '12 minutes', NULL, NULL,
                T - interval '8 minutes', '출발이 임박해 명단 변경이 어렵습니다. 결석은 학원으로 전화 주세요.');
    END IF;
    -- 오늘 1호차 하원(①구간: 즉시 반영된 취소 2 · 위치 변경 1)
    SELECT array_agg(wa.student_id ORDER BY wa.student_id) INTO v_ids
    FROM weekly_address wa JOIN route r ON r.bus_id = 1 AND r.weekday = wa.weekday AND r.direction = 'from_academy'
    JOIN route_stop rs ON rs.route_id = r.id AND rs.stop_id = wa.stop_id
    WHERE wa.weekday = pg_temp.qa_wd(((T + interval '50 minutes') AT TIME ZONE 'Asia/Seoul')::date) AND wa.direction = 'from_academy';
    IF array_length(v_ids, 1) >= 6 THEN
        PERFORM pg_temp.qa_request(v_a1_from, v_ids[2], 'change_request', 'cancel', 'approved', 1, T - interval '3 hours', NULL,
                '병원 진료로 조퇴합니다', NULL, NULL);
        PERFORM pg_temp.qa_request(v_a1_from, v_ids[5], 'change_request', 'cancel', 'approved', 1, T - interval '70 minutes', NULL,
                '가족 외식이 있어 보호자가 데리러 갑니다', NULL, NULL);
        PERFORM pg_temp.qa_request(v_a1_from, v_ids[6], 'change_request', 'relocate', 'approved', 1, T - interval '2 hours',
                (SELECT stop_id FROM route_stop rs JOIN route r ON r.id = rs.route_id WHERE r.bus_id = 1 AND r.direction = 'from_academy' AND rs.seq = 9
                 AND r.weekday = pg_temp.qa_wd(((T + interval '50 minutes') AT TIME ZONE 'Asia/Seoul')::date)),
                '오늘은 할머니 댁으로 하원합니다', NULL, NULL);
    END IF;
    -- 내일(①구간: 전날 접수된 일일 변경 — 위치 변경 3 · 취소 2)
    FOR a IN
        SELECT r.id AS run_id, rr.student_id, rr.n, rs2.stop_id AS other_stop
        FROM run r
        JOIN LATERAL (
            SELECT wa.student_id, row_number() OVER (ORDER BY wa.student_id) AS n
            FROM weekly_address wa JOIN route ro ON ro.bus_id = r.bus_id AND ro.weekday = wa.weekday AND ro.direction = r.direction
            JOIN route_stop rs ON rs.route_id = ro.id AND rs.stop_id = wa.stop_id
            WHERE wa.weekday = pg_temp.qa_wd(r.service_date) AND wa.direction = r.direction
        ) rr ON rr.n IN (3, 8)
        JOIN route ro2 ON ro2.bus_id = r.bus_id AND ro2.weekday = pg_temp.qa_wd(r.service_date) AND ro2.direction = r.direction
        JOIN route_stop rs2 ON rs2.route_id = ro2.id AND rs2.seq = 5
        WHERE r.service_date = v_today + 1 AND r.bus_id IN (1, 2, 5) AND r.canceled_at IS NULL
          AND r.depart_time > T + interval '3 hours'
    LOOP
        IF a.n = 3 THEN
            PERFORM pg_temp.qa_request(a.run_id, a.student_id, 'change_request', 'relocate', 'approved', 1,
                    T - make_interval(mins => 30 + (a.run_id % 90)::int), a.other_stop, '내일은 이모 댁에서 타고 내립니다', NULL, NULL);
        ELSE
            PERFORM pg_temp.qa_request(a.run_id, a.student_id, 'change_request', 'cancel', 'approved', 1,
                    T - make_interval(mins => 15 + (a.run_id % 60)::int), NULL, '내일 학교 행사로 결석합니다', NULL, NULL);
        END IF;
    END LOOP;
    -- 지난 이력 — ②구간 요청의 승인 · 거절 · 기한 초과(자동 거절)
    FOR a IN
        SELECT r.id AS run_id, r.depart_time, rr.student_id, row_number() OVER (ORDER BY r.depart_time) AS n
        FROM run r JOIN LATERAL (SELECT student_id FROM run_rider WHERE run_id = r.id AND status = 'alighted' ORDER BY id LIMIT 1) rr ON true
        WHERE r.service_date BETWEEN v_today - 6 AND v_today - 1 AND r.status = 'finished' AND r.bus_id IN (1, 2, 3, 5)
          AND r.id % 4 = 0
    LOOP
        IF a.n % 3 = 0 THEN
            PERFORM pg_temp.qa_request(a.run_id, a.student_id, 'intent', 'cancel', 'rejected', 2, a.depart_time - interval '20 minutes',
                    NULL, NULL, a.depart_time - interval '12 minutes', '이미 출발 준비 중이라 변경이 어렵습니다.');
        ELSIF a.n % 3 = 1 THEN
            PERFORM pg_temp.qa_request(a.run_id, a.student_id, 'intent', 'cancel', 'auto_rejected', 2,
                    a.depart_time - interval '15 minutes', NULL, NULL, a.depart_time, NULL);
        ELSE
            PERFORM pg_temp.qa_request(a.run_id, a.student_id, 'change_request', 'relocate', 'rejected', 2,
                    a.depart_time - interval '25 minutes', NULL, '학원 앞 편의점에서 내려 주세요', a.depart_time - interval '18 minutes',
                    '노선에 없는 위치라 출발 직전 변경이 어렵습니다.');
        END IF;
    END LOOP;

    -- ⑤ 지연 — 오늘 2호차 등원(운행 중) · 이틀 전 2호차 하원 · 닷새 전 B 1호차 등원
    FOR a IN
        SELECT * FROM (VALUES
            (v_a2_to, 10, 'traffic', '중동로 공사 구간 정체로 조금 늦어집니다', T - interval '1 minute'),
            ((SELECT id FROM run WHERE bus_id = 2 AND service_date = v_today - 2 AND direction = 'from_academy' AND status = 'finished'),
             15, 'weather', '폭우로 서행 중입니다', NULL::timestamptz),
            ((SELECT id FROM run WHERE bus_id = 5 AND service_date = v_today - 5 AND direction = 'to_academy' AND status = 'finished'),
             5, 'prev_stop_wait', '앞 승하차지 학생 대기로 잠시 늦어집니다', NULL::timestamptz)
        ) AS x(run_id, minutes, reason, message, sent_at)
    LOOP
        CONTINUE WHEN a.run_id IS NULL;
        INSERT INTO delay_notice (run_id, sent_by_account_id, minutes, reason, message, sent_at)
        SELECT a.run_id, m.account_id, a.minutes, a.reason, a.message,
               COALESCE(a.sent_at, r.started_at + interval '8 minutes')
        FROM run r JOIN assignment asg ON asg.run_id = r.id AND asg.role = 'driver' JOIN manager m ON m.id = asg.manager_id
        WHERE r.id = a.run_id;
        FOR s IN
            SELECT DISTINCT g.account_id AS acc, rr.student_id, st.name AS sname,
                   COALESCE(a.sent_at, r.started_at + interval '8 minutes') AS at
            FROM run r JOIN run_rider rr ON rr.run_id = r.id AND rr.status <> 'absent'
            JOIN student st ON st.id = rr.student_id
            JOIN guardian_student gs ON gs.student_id = rr.student_id JOIN guardian g ON g.id = gs.guardian_id
            WHERE r.id = a.run_id
        LOOP
            PERFORM pg_temp.qa_notify(s.acc, 'parent', s.student_id, a.run_id, 'delay', '지연 알림',
                    format('%s 학생이 탄 버스 — %s 현재 예상 지연 %s분입니다.', s.sname,
                           CASE a.reason WHEN 'traffic' THEN '교통 정체로 인해 지연되고 있습니다.'
                                         WHEN 'weather' THEN '기상 상황으로 인해 지연되고 있습니다.'
                                         ELSE '이전 승하차지 대기로 인해 지연되고 있습니다.' END, a.minutes),
                    s.at, format('delay:%s:guardian:%s:%s:%s', a.run_id, s.acc, s.student_id, s.at));
        END LOOP;
    END LOOP;

    -- ⑥ 비상 신고 — 어제 2호차 하원 차량 고장(확인 · 조치 메모) · 나흘 전 B 학생 응급(확인) · 엿새 전 1호차 오작동(취소)
    FOR a IN
        SELECT * FROM (VALUES
            (2, v_today - 1, 'from_academy', 'vehicle_fault', '타이어 공기압 경고등이 켜졌습니다', '정비소 점검 후 20분 뒤 운행 재개 — 보호자 안내 완료', false),
            (5, v_today - 4, 'to_academy', 'student_emergency', '학생이 코피를 흘려 잠시 정차했습니다', '응급 처치 후 학원 도착, 보호자 통화 완료', false),
            (1, v_today - 6, 'to_academy', 'etc', '비상 버튼을 잘못 눌렀습니다', NULL, true)
        ) AS x(bus_id, service_date, direction, type, memo, ack_memo, canceled)
    LOOP
        SELECT r.id, r.academy_id, b.bus_no, r.started_at, rs.lat, rs.lng,
               (SELECT count(*) FROM run_rider WHERE run_id = r.id AND status <> 'absent') AS riders, m.account_id AS raiser
          INTO s
          FROM run r JOIN bus b ON b.id = r.bus_id
          JOIN assignment asg ON asg.run_id = r.id AND asg.role = 'escort' JOIN manager m ON m.id = asg.manager_id
          JOIN LATERAL (SELECT st.lat, st.lng FROM run_stop x JOIN stop st ON st.id = x.stop_id
                        JOIN route_version v ON v.id = x.route_version_id WHERE v.confirmed_route_id = r.id AND x.seq = 4) rs ON true
         WHERE r.bus_id = a.bus_id AND r.service_date = a.service_date AND r.direction = a.direction AND r.status = 'finished';
        CONTINUE WHEN s.id IS NULL;
        INSERT INTO emergency_alert (academy_id, run_id, bus_no, raised_by, raised_by_role, type, memo, lat, lng, rider_count,
                                     occurred_at, received_at, client_key, acked_by, acked_at, ack_memo, canceled_at, position_recorded_at)
        VALUES (s.academy_id, s.id, s.bus_no, s.raiser, 'escort', a.type, a.memo, s.lat, s.lng, s.riders,
                s.started_at + interval '12 minutes', s.started_at + interval '12 minutes 2 seconds', gen_random_uuid(),
                CASE WHEN NOT a.canceled THEN (SELECT account_id FROM academy_staff WHERE academy_id = s.academy_id AND status = 'active') END,
                CASE WHEN NOT a.canceled THEN s.started_at + interval '14 minutes' END, a.ack_memo,
                CASE WHEN a.canceled THEN s.started_at + interval '13 minutes' END, s.started_at + interval '11 minutes 58 seconds')
        RETURNING id INTO v_alert;
        FOR v_rider IN SELECT account_id FROM academy_staff WHERE academy_id = s.academy_id AND status = 'active'
                       UNION SELECT v_sys LOOP
            PERFORM pg_temp.qa_notify(v_rider, CASE WHEN v_rider = v_sys THEN 'system_admin' ELSE 'staff' END, NULL, s.id, 'emergency',
                    '비상 상황 발생', format('%s 차량에서 %s 상황이 발생했습니다. 즉시 확인해 주세요.', s.bus_no,
                        CASE a.type WHEN 'vehicle_fault' THEN '차량 고장' WHEN 'student_emergency' THEN '학생 응급'
                                    WHEN 'accident' THEN '사고' ELSE '기타 비상' END),
                    s.started_at + interval '12 minutes', format('emergency:%s:%s', v_alert, v_rider));
            IF a.canceled THEN
                PERFORM pg_temp.qa_notify(v_rider, CASE WHEN v_rider = v_sys THEN 'system_admin' ELSE 'staff' END, NULL, s.id,
                        'emergency_canceled', '비상 신고 취소', format('%s 차량의 비상 신고가 취소되었습니다.', s.bus_no),
                        s.started_at + interval '13 minutes', format('emergency_canceled:%s:%s', v_alert, v_rider));
            END IF;
        END LOOP;
    END LOOP;

    -- ⑦ 현장 예외 보고 — 보호자 부재 · 도로 통제 · 차량 이상
    FOR a IN
        SELECT * FROM (VALUES
            (1, v_today - 2, 'from_academy', 'guardian_absent', '하원 시 보호자 부재 — 경비실 인계 후 보호자와 통화 완료'),
            (2, v_today - 5, 'to_academy', 'road_block', '계남로 도로 공사로 우회 운행(약 5분 추가)'),
            (5, v_today - 1, 'from_academy', 'vehicle_issue', '에어컨 고장 — 창문을 열고 운행, 정비 예약함')
        ) AS x(bus_id, service_date, direction, type, memo)
    LOOP
        SELECT r.id, r.academy_id, r.started_at, m.account_id AS reporter,
               (SELECT id FROM run_rider WHERE run_id = r.id AND status = 'alighted' ORDER BY id LIMIT 1) AS rider
          INTO s
          FROM run r JOIN assignment asg ON asg.run_id = r.id AND asg.role = 'escort' JOIN manager m ON m.id = asg.manager_id
         WHERE r.bus_id = a.bus_id AND r.service_date = a.service_date AND r.direction = a.direction AND r.status = 'finished';
        CONTINUE WHEN s.id IS NULL;
        INSERT INTO exception_report (academy_id, run_id, run_rider_id, type, memo, reported_by, reported_at)
        VALUES (s.academy_id, s.id, CASE WHEN a.type = 'guardian_absent' THEN s.rider END, a.type, a.memo, s.reporter,
                s.started_at + interval '20 minutes');
        FOR v_rider IN SELECT account_id FROM academy_staff WHERE academy_id = s.academy_id AND status = 'active' LOOP
            PERFORM pg_temp.qa_notify(v_rider, 'staff', NULL, s.id, 'exception_reported', '현장 예외 보고 접수',
                    '현장에서 예외 상황이 보고됐습니다. 목록에서 확인해 주세요.', s.started_at + interval '20 minutes',
                    format('exception_reported:%s:%s:%s', s.id, v_rider, s.started_at + interval '20 minutes'));
        END LOOP;
    END LOOP;

    -- ⑧ 가입 결정 알림 — 최근 30일 안에 승인된 학부모
    FOR a IN SELECT sr.account_id, sr.decided_at FROM signup_request sr JOIN account ac ON ac.id = sr.account_id
             WHERE sr.status = 'accepted' AND ac.role = 'parent' AND sr.decided_at > now() - interval '30 days' LOOP
        PERFORM pg_temp.qa_notify(a.account_id, 'parent', NULL, NULL, 'signup_decided', '가입 승인 안내',
                '가입이 승인되었습니다. 로그인 후 이용해 주세요.', a.decided_at, format('signup_decided:na:%s:%s', a.account_id, a.decided_at));
    END LOOP;

    -- ⑨ 접속 기록 — 마지막 로그인 성공 · 차단 계정의 실패 5회와 차단
    INSERT INTO audit_log (academy_id, actor_account_id, actor_login_id, category, action, target_type, target_id, ip, occurred_at)
    SELECT academy_id, id, login_id, 'login', 'login_success', 'account', id,
           ('211.36.' || (id % 200) || '.' || (10 + id % 90))::inet, last_login_at
    FROM account WHERE last_login_at IS NOT NULL;
    INSERT INTO audit_log (academy_id, actor_account_id, actor_login_id, category, action, target_type, target_id, ip, block_event, occurred_at)
    SELECT ac.academy_id, ac.id, ac.login_id, 'login', CASE WHEN n = 6 THEN 'block' ELSE 'login_fail' END, 'account', ac.id,
           '118.235.12.40'::inet, n = 6, ac.blocked_at - make_interval(mins => 6 - n)
    FROM account ac CROSS JOIN generate_series(1, 6) n WHERE ac.status = 'blocked';
END
$main$;

DROP FUNCTION pg_temp.qa_run(bigint, text, timestamptz, text, int, boolean);
DROP FUNCTION pg_temp.qa_request(bigint, bigint, text, text, text, int, timestamptz, bigint, text, timestamptz, text);
DROP FUNCTION pg_temp.qa_guardians(bigint);
DROP FUNCTION pg_temp.qa_notify(bigint, text, bigint, bigint, text, text, text, timestamptz, text);
DROP FUNCTION pg_temp.qa_h(text);
DROP FUNCTION pg_temp.qa_wd(date);
DROP TABLE qa_road;
DROP TABLE qa_bus;
